"""Synthesises WH-1000XM5 frame fixtures from libmdr's protocol definitions.

Usage: python3 -I gen.py > attach.frames

Framing (libmdr, MIT): 0x3E, then type, seq, Int32BE size, data and a 1-byte
sum checksum, escaped with 0x3D (3C/3D/3E -> 3D 2C/2D/2E), then 0x3C.
"""

def escape(body):
    out = bytearray()
    for b in body:
        out += bytes([0x3D, b - 0x10]) if b in (0x3C, 0x3D, 0x3E) else bytes([b])
    return bytes(out)

def pack(data_type, seq, data):
    body = bytes([data_type, seq]) + len(data).to_bytes(4, "big") + data
    body += bytes([sum(body) & 0xFF])
    return b"\x3e" + escape(body) + b"\x3c"

MDR, ACK = 0x0C, 0x01
H = lambda s: bytes.fromhex(s)

HEADER = """\
# WH-1000XM5 Attach: identification, support functions, battery and noise control.
# Synthesised from libmdr's protocol definitions (MIT, mos9527/SonyHeadphonesClient)
# until a real capture exists; generated by gen.py in this directory. The
# protocol info reply is the XM5 fw 1.1.3 one; the support function list is
# made up but, like the real fw 2.5.1 one, lists battery 0x20 and NC/ASM 0x6b
# (NCASM type 0x17). Battery: 70 %. Noise control: Ambient, Focus on Voice on,
# Ambient Level 10. Equalizer: Bright, Clear Bass +2, Bands -1 0 +3 +5 +10.
# Then a battery notification of 69 %."""

# (direction, type, seq, data, comment); the model name reply identifies the
# Model, so it and later records carry the Model's slug, as the frame log does.
STEPS = [
    (">>", MDR, 0, "00 00", "GET protocol info"),
    ("<<", ACK, 1, "", None),
    ("<<", MDR, 0, "01 00 03 00 00 00 00 00", None),
    (">>", ACK, 1, "", None),
    (">>", MDR, 1, "04 01", "GET model name"),
    ("<<", ACK, 0, "", None),
    ("<<", MDR, 1, "05 01 0a" + b"WH-1000XM5".hex(), None),
    (">>", ACK, 0, "", None),
    (">>", MDR, 0, "06 00", "GET support functions"),
    ("<<", ACK, 1, "", None),
    ("<<", MDR, 0, "07 00 02 20 ff 6b 08", None),
    (">>", ACK, 1, "", None),
    (">>", MDR, 1, "22 00", "GET battery"),
    ("<<", ACK, 0, "", None),
    ("<<", MDR, 1, "23 00 46 00", None),
    (">>", ACK, 0, "", None),
    (">>", MDR, 0, "66 17", "GET noise control"),
    ("<<", ACK, 1, "", None),
    ("<<", MDR, 0, "67 17 01 01 01 01 0a", None),
    (">>", ACK, 1, "", None),
    (">>", MDR, 1, "56 00", "GET Equalizer"),
    ("<<", ACK, 0, "", None),
    ("<<", MDR, 1, "57 00 10 06 0c 09 0a 0d 0f 14", None),
    (">>", ACK, 0, "", None),
    ("<<", MDR, 0, "25 00 45 00", None),
    (">>", ACK, 1, "", None),
]
IDENTIFIED_AT = 6

print(HEADER)
for i, (direction, data_type, seq, data, comment) in enumerate(STEPS):
    if comment:
        print(f"# {comment}")
    model = "wh-1000xm5" if i >= IDENTIFIED_AT else "sony"
    frame = pack(data_type, seq, H(data)).hex(" ")
    print(f"2026-10-11T12:00:00.{i * 10:03d}Z {model} {direction} {frame}")
